from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PlanUploadOperationStatusASMV1(SchemaObject):
    plan_id = SchemaField(name='planId', not_null=True)
    raml_parsing_errors = SchemaField(name='ramlParsingErrors')
    incorrect_objects_feedback = SchemaField(name='incorrectObjectsFeedback', not_null=True)
    action_id = SchemaField(name='actionId', not_null=True)
    links = SchemaField(name="links", optional=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='errorMessage', optional=True)
    procedure_state = SchemaField(name='procedureState', not_null=True)

    def __init__(self, plan_id, raml_parsing_errors, incorrect_objects_feedback,
                 action_id, links, status, error_message, procedure_state):
        self.plan_id = plan_id
        self.raml_parsing_errors = raml_parsing_errors
        self.incorrect_objects_feedback = incorrect_objects_feedback
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message
        self.procedure_state = procedure_state

        super(PlanUploadOperationStatusASMV1, self).__init__()
